package edu.bis701.exp05;
import com.mongodb.client.*;import com.mongodb.client.model.*;import org.bson.Document;import java.util.*;
public class MongoAggregation{public static void main(String[]a){String uri=System.getenv().getOrDefault("MONGODB_URI","mongodb://localhost:27017");String dbName="bis701_lab",collName="employees";try(MongoClient client=MongoClients.create(uri)){MongoDatabase db=client.getDatabase(dbName);MongoCollection<Document> col=db.getCollection(collName);col.deleteMany(new Document("labDemo",true));List<Document> employees=Arrays.asList(new Document("_id",1).append("name","John Doe").append("age",30).append("department","HR").append("salary",60000).append("labDemo",true),new Document("_id",2).append("name","Jane Smith").append("age",25).append("department","Engineering").append("salary",80000).append("labDemo",true),new Document("_id",3).append("name","Sam Johnson").append("age",45).append("department","Engineering").append("salary",120000).append("labDemo",true),new Document("_id",4).append("name","Chris Lee").append("age",35).append("department","Marketing").append("salary",75000).append("labDemo",true),new Document("_id",5).append("name","Emma Brown").append("age",29).append("department","HR").append("salary",65000).append("labDemo",true),new Document("_id",6).append("name","Alex Taylor").append("age",32).append("department","Engineering").append("salary",95000).append("labDemo",true),new Document("_id",7).append("name","Sophia Williams").append("age",28).append("department","Marketing").append("salary",70000).append("labDemo",true),new Document("_id",8).append("name","James Davis").append("age",50).append("department","Management").append("salary",150000).append("labDemo",true));col.insertMany(employees);System.out.println("Inserted employee records:");for(Document d:col.find(new Document("labDemo",true)))System.out.println(d.toJson());System.out.println("Employee count by department:");for(Document d:col.aggregate(Arrays.asList(Aggregates.match(new Document("labDemo",true)),Aggregates.group("$department",Accumulators.sum("totalEmployees",1)),Aggregates.sort(Sorts.ascending("_id")))))System.out.println(d.toJson());System.out.println("Average salary by department:");for(Document d:col.aggregate(Arrays.asList(Aggregates.match(new Document("labDemo",true)),Aggregates.group("$department",Accumulators.avg("averageSalary","$salary")),Aggregates.sort(Sorts.ascending("_id")))))System.out.println(d.toJson());}}}
